export function nextGeneration(liveCells: Cell[]): Cell[] {
  return liveCells.filter(([x, y]) =>
    liveCells.some(([nx, ny]) => Math.abs(nx - x) <= 1 && Math.abs(ny - y) <= 1 && !(nx === x && ny === y))
      ? liveCells.filter(
          ([nx, ny]) =>
            Math.abs(nx - x) <= 1 && Math.abs(ny - y) <= 1 && !(nx === x && ny === y),
        ).length === 2
      : false,
  );
}

