export type Cell = [x: number, y: number];

function isSameCell([x, y]: Cell, [otherX, otherY]: Cell): boolean {
  return x === otherX && y === otherY;
}

function isNeighbourOf(cell: Cell, candidate: Cell): boolean {
  const [x, y] = cell;
  const [candidateX, candidateY] = candidate;
  const isWithinOneStep =
    Math.abs(candidateX - x) <= 1 && Math.abs(candidateY - y) <= 1;
  return isWithinOneStep && !isSameCell(cell, candidate);
}

function countNeighbours(liveCells: Cell[], cell: Cell): number {
  return liveCells.filter((candidate) => isNeighbourOf(cell, candidate)).length;
}

function survives(cell: Cell, liveCells: Cell[]): boolean {
  return countNeighbours(liveCells, cell) === 2;
}

export function nextGeneration(liveCells: Cell[]): Cell[] {
  return liveCells.filter((cell) => survives(cell, liveCells));
}

