function neighbourhoodOf([x, y]: Cell): Cell[] {
  const offsets = [-1, 0, 1];
  return offsets.flatMap((dx) =>
    offsets
      .filter((dy) => !(dx === 0 && dy === 0))
      .map((dy): Cell => [x + dx, y + dy]),
  );
}

function isBorn(cell: Cell, liveCells: Cell[]): boolean {
  return (
    !liveCells.some((live) => isSameCell(live, cell)) &&
    countNeighbours(liveCells, cell) === 3
  );
}

export function nextGeneration(liveCells: Cell[]): Cell[] {
  const survivors = liveCells.filter((cell) => survives(cell, liveCells));
  const births = liveCells
    .flatMap(neighbourhoodOf)
    .filter((cell) => isBorn(cell, liveCells))
    .filter(
      (cell, index, all) =>
        all.findIndex((other) => isSameCell(other, cell)) === index,
    );
  return [...survivors, ...births];
}

